import React from 'react';
import { Link } from 'gatsby';
import { Content, Header, Layout, SEO, SectionTitle, Wrapper } from '../components';
import config from '../../config/SiteConfig';

export default function NotFoundPage() {
  return (
    <Layout>
      <Header>
        <Link to="/">
          <strong>{config.siteTitle}</strong>
        </Link>
        <SectionTitle>404</SectionTitle>
      </Header>
      <Wrapper>
        <Content>
          <h2>페이지를 찾을 수 없습니다.</h2>
          <p>주소가 변경되었거나 삭제된 페이지입니다.</p>
          <Link to="/">홈으로 돌아가기</Link>
        </Content>
      </Wrapper>
    </Layout>
  );
}

export const Head = () => (
  <SEO pathname="/404/" title={`페이지를 찾을 수 없습니다 | ${config.siteTitle}`} noIndex />
);
